style.css:
/* ROBLOX — DARK BABY BLUE THEME (WHITE TEXT) */

html, body {
  background-image: url("https://i.pinimg.com/1200x/eb/24/86/eb2486902a4325844d64d40ecd6f9294.jpg") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  color: #ffffff !important;
}

/* ===== DARK OVERLAY ===== */
html::before {
  content: "";
  position: fixed;
  inset: 0;
  background-color: rgba(10, 18, 30, 0.94);
  pointer-events: none;
  z-index: 0;
}

/* ===== KEEP CONTENT ABOVE OVERLAY ===== */
body, body * {
  position: relative;
  z-index: 1;
  color: #ffffff !important;
}

/* ===== INPUTS ===== */
textarea,
input,
select {
  background-color: rgba(20, 28, 45, 0.95) !important;
  color: #ffffff !important;
  border-radius: 14px !important;
  border: 1px solid rgba(160, 200, 255, 0.35) !important;
}

/* ===== BUTTONS ===== */
button {
  background-color: rgba(120, 170, 255, 0.85) !important;
  color: #0b1220 !important;
  border-radius: 16px !important;
  font-weight: 600 !important;
}

button:hover {
  background-color: rgba(160, 200, 255, 0.95) !important;
}

/* ===== LINKS ===== */
a {
  color: #9ecbff !important;
}
